const { expect } = require("chai");
const { ethers } = require("hardhat");

describe("MetaCoin", function () {
  let metaCoin;
  let owner;
  let user1;
  let user2;

  beforeEach(async function () {
    [owner, user1, user2] = await ethers.getSigners();
    const MetaCoin = await ethers.getContractFactory("MetaCoin");
    metaCoin = await MetaCoin.deploy();
    await metaCoin.waitForDeployment();
  });

  describe("Deployment", function () {
    it("Should assign initial balance to the deployer", async function () {
      expect(await metaCoin.getBalance(owner.address)).to.equal(10000n);
    });

    it("Should have zero balance for other accounts", async function () {
      expect(await metaCoin.getBalance(user1.address)).to.equal(0n);
      expect(await metaCoin.getBalance(user2.address)).to.equal(0n);
    });
  });

  describe("sendCoin", function () {
    it("Should transfer coins between accounts", async function () {
      const amount = 100n;
      await expect(metaCoin.sendCoin(user1.address, amount))
        .to.emit(metaCoin, "Transfer")
        .withArgs(owner.address, user1.address, amount);

      expect(await metaCoin.getBalance(owner.address)).to.equal(9900n);
      expect(await metaCoin.getBalance(user1.address)).to.equal(amount);
    });

    it("Should fail if sender doesn't have enough coins", async function () {
      const amount = 10001n;
      await expect(metaCoin.sendCoin(user1.address, amount)).to.be.reverted;
      expect(await metaCoin.getBalance(owner.address)).to.equal(10000n);
      expect(await metaCoin.getBalance(user1.address)).to.equal(0n);
    });

    it("Should fail when transferring to zero address", async function () {
      const amount = 100n;
      await expect(metaCoin.sendCoin(ethers.ZeroAddress, amount)).to.be.reverted;
    });

    it("Should return false when transfer fails", async function () {
      const amount = 10001n;
      expect(await metaCoin.sendCoin(user1.address, amount)).to.be.false;
    });
  });

  describe("getBalance", function () {
    it("Should return correct balance for accounts", async function () {
      expect(await metaCoin.getBalance(owner.address)).to.equal(10000n);
      expect(await metaCoin.getBalance(user1.address)).to.equal(0n);
    });
  });

  describe("getBalanceInEth", function () {
    it("Should return balance multiplied by 2", async function () {
      expect(await metaCoin.getBalanceInEth(owner.address)).to.equal(20000n);
      expect(await metaCoin.getBalanceInEth(user1.address)).to.equal(0n);
    });

    it("Should update when balance changes", async function () {
      const amount = 100n;
      await metaCoin.sendCoin(user1.address, amount);
      expect(await metaCoin.getBalanceInEth(owner.address)).to.equal(19800n);
      expect(await metaCoin.getBalanceInEth(user1.address)).to.equal(200n);
    });
  });
});
